#!/usr/bin/env python3
"""Textures for the seashore showcase map (project/test_scenes/seashore/tex/).

Two kinds:

* PROCEDURAL, regenerated by ./run_seashore.sh on every export and
  gitignored (they are build output): the animated sea (an 8-frame flipbook
  that tiles in space AND loops in time exactly — every wave component has an
  integer number of cycles across the tile and over the loop), the lacy surf
  foam band, the sun-glitter sparkle flipbook, a sun glow, a blob shadow, a
  spray puff and the spray flipbook (a clump tearing into droplets).

* PAINTED, from source art (low-res image-model generations, kept out of git
  at 2048 px): sand, rock, palm bark, a palm frond, a whole palm for the
  distant billboards, beach shrubs, a gull, driftwood planks, the sky panorama,
  the distant island, grass and the jungle backdrop. These PSP-sized results
  ARE committed (the sources cannot be regenerated deterministically). Pass the
  directory holding the sources with --src; without it they are left alone.

Sizes are PSP sizes: power of two, 64-256 px (the GE's texture cache is ~8 KB;
see retro_engine/psp/OPTIMIZATION.md §3).

    python3 retro_engine/gen_seashore_textures.py [--src DIR]
"""
import argparse
import math
import os

import numpy as np
from PIL import Image, ImageFilter

OUT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "project",
                   "test_scenes", "seashore", "tex")
RNG = np.random.default_rng(1149)


def save(arr, name):
    arr = np.clip(arr, 0, 255).astype(np.uint8)
    mode = "RGBA" if arr.shape[2] == 4 else "RGB"
    Image.fromarray(arr, mode).save(os.path.join(OUT, name), optimize=True)


def grid(n):
    y, x = np.mgrid[0:n, 0:n].astype(np.float64)
    return x / n, y / n


# ── procedural ───────────────────────────────────────────────────────────

def periodic_field(n, t, comps):
    """Sum of plane waves with INTEGER wave vectors (tiles) and integer temporal
    frequencies (loops over t in [0,1))."""
    x, y = grid(n)
    f = np.zeros((n, n))
    for kx, ky, w, amp, ph in comps:
        f += amp * np.sin(2 * math.pi * (kx * x + ky * y + w * t) + ph)
    return f


def sea_components(seed, count, kmax):
    r = np.random.default_rng(seed)
    comps = []
    for _ in range(count):
        kx, ky = 0, 0
        while kx == 0 and ky == 0:
            kx, ky = int(r.integers(-kmax, kmax + 1)), int(r.integers(-kmax, kmax + 1))
        k = math.hypot(kx, ky)
        w = int(r.choice([-2, -1, 1, 2]))
        comps.append((kx, ky, w, 1.0 / (k ** 0.9), r.uniform(0, 2 * math.pi)))
    return comps


def sea_frames(frames=8, n=128):
    comps = sea_components(7, 14, 6)
    ripple = sea_components(19, 10, 11)
    deep = np.array([18, 74, 112], float)
    mid = np.array([30, 118, 150], float)
    light = np.array([150, 214, 222], float)
    for i in range(frames):
        t = i / frames
        f = periodic_field(n, t, comps)
        f = (f - f.min()) / (f.max() - f.min())
        # caustic-like bright ridges: where the field crosses its mid value
        rid = periodic_field(n, t, ripple)
        rid = np.exp(-(rid ** 2) * 6.0)
        body = deep[None, None] * (1 - f[..., None]) + mid[None, None] * f[..., None]
        col = body + (light - body) * (rid[..., None] * 0.45 * (0.4 + f[..., None]))
        rgb = col
        save(rgb, f"sea_f{i}.png")
        # the shallow layer: the same motion, lighter and translucent (its
        # alpha is mostly the vertex alpha; 238 keeps the texture BLEND)
        shallow = rgb * 0.75 + np.array([70, 150, 140], float) * 0.25
        a = np.full((n, n, 1), 238.0)
        save(np.concatenate([shallow + rid[..., None] * 25, a], axis=2), f"shallow_f{i}.png")


def foam_band(w=256, h=64):
    """The surf strip: U runs along the shoreline (tiles), V across it — the
    landward edge (V=0) is the bright breaking line, the body behind it is a
    lacy, holed sheet that thins toward V=1."""
    x = np.arange(w)[None, :] / w
    y = np.arange(h)[:, None] / h
    # lace: band-passed white noise, periodic in both axes (FFT filtering
    # wraps), thresholded into cells with holes — the look of spent surf
    r = np.random.default_rng(3)
    noise = r.standard_normal((h, w))
    fy = np.fft.fftfreq(h)[:, None] * h
    fx = np.fft.fftfreq(w)[None, :] * w / 4.0   # 4:1 texel aspect: cells stay round on the strip
    k = np.hypot(fx, fy)
    band = np.exp(-((k - 7.0) / 3.5) ** 2)
    lace = np.real(np.fft.ifft2(np.fft.fft2(noise) * band))
    lace = (lace - lace.min()) / (lace.max() - lace.min())
    holes = np.clip((lace - 0.5) * 5.0, 0, 1)
    edge = np.exp(-((y - 0.07) / 0.06) ** 2)
    edge_wobble = np.exp(-((y - 0.07 - 0.04 * np.sin(2 * math.pi * 3 * x)) / 0.05) ** 2)
    body = holes * np.clip(1.15 - y * 1.25, 0, 1)
    a = np.clip(np.maximum(edge * 0.95, edge_wobble * 0.9) + body * 0.8, 0, 1)
    a[0, :] *= 0.5
    rgb = np.ones((h, w, 3)) * np.array([240, 248, 250])
    rgb -= (1 - a[..., None]) * np.array([30, 15, 5])
    save(np.concatenate([rgb, a[..., None] * 255], axis=2), "surf_foam.png")


def sparkle_frames(frames=4, n=64):
    """Sun glitter for the additive sun path: sparse sharp glints that blink
    over the loop (each glint has its own phase)."""
    r = np.random.default_rng(11)
    pts = r.uniform(0, n, (70, 2))
    ph = r.uniform(0, 1, 70)
    size = r.uniform(0.9, 2.0, 70)
    yy, xx = np.mgrid[0:n, 0:n].astype(float)
    for i in range(frames):
        t = i / frames
        img = np.zeros((n, n))
        for (px, py), p, s in zip(pts, ph, size):
            b = max(0.0, math.cos(2 * math.pi * (t - p))) ** 3
            if b < 0.02:
                continue
            for ox in (-n, 0, n):
                for oy in (-n, 0, n):
                    dx = xx - px - ox
                    dy = yy - py - oy
                    d2 = dx * dx + dy * dy
                    img += b * np.exp(-d2 / (0.5 * s * s))
                    # a short horizontal streak: glints on water stretch sideways
                    img += 0.35 * b * np.exp(-(dx * dx) / (6 * s * s) - (dy * dy) / (0.25 * s))
        # a soft base shimmer under the glints: the path reads as a band of
        # light from afar, the glints as sparkle up close
        shim = 0.5 + 0.5 * periodic_field(n, t, sea_components(23 + 0, 8, 4)) / 3.0
        img = np.clip(img + 0.45 + 0.3 * np.clip(shim, 0, 1), 0, 1)
        # brightness lives in ALPHA only: the additive blend is src * srcA, so
        # carrying it in RGB as well squares it away (a 0.3 shimmer -> 9%)
        rgb = np.ones((n, n, 3)) * np.array([255, 245, 215], float)
        save(np.concatenate([rgb, img[..., None] * 255], axis=2), f"glint_f{i}.png")


def radial(n, falloff, color, name, power=1.0):
    yy, xx = np.mgrid[0:n, 0:n].astype(float)
    d = np.hypot(xx - (n - 1) / 2, yy - (n - 1) / 2) / (n / 2)
    a = np.clip(falloff(d), 0, 1) ** power
    rgb = np.ones((n, n, 3)) * np.array(color, float)
    save(np.concatenate([rgb, a[..., None] * 255], axis=2), name)


def spray_sheet(cell=64):
    """Spray flipbook, 2x2 cells (spray_2x2_sheet.png), one burst's life:
    a dense foam clump (frame 0) that tears into lacy fragments and flying
    droplets (frame 3). Soft alpha, white tops, blue-grey self-shaded
    undersides — a puff of spray is lit from above and dark underneath."""
    r = np.random.default_rng(31)
    yy, xx = np.mgrid[0:cell, 0:cell].astype(float)
    # one shared cluster, so the four frames read as the same burst evolving
    blobs = [(r.normal(0, 0.09), r.normal(0.03, 0.08), r.uniform(0.035, 0.075)) for _ in range(16)]
    drops = [(r.normal(0, 0.22), r.normal(-0.04, 0.2), r.uniform(0.008, 0.018)) for _ in range(40)]
    noise = r.standard_normal((cell, cell))
    fy = np.fft.fftfreq(cell)[:, None] * cell
    fx = np.fft.fftfreq(cell)[None, :] * cell
    band = np.exp(-((np.hypot(fx, fy) - 11.0) / 4.0) ** 2)
    lace = np.real(np.fft.ifft2(np.fft.fft2(noise) * band))
    lace = (lace - lace.min()) / (lace.max() - lace.min())
    sheet = np.zeros((cell * 2, cell * 2, 4))
    rr = np.hypot(xx - cell * 0.5, yy - cell * 0.5) / cell
    for f in range(4):
        spread = 1.0 + 0.5 * f           # the burst expands...
        tear = 0.12 + 0.13 * f           # ...tears into holes...
        fade = 1.0 - 0.16 * f            # ...and thins out
        dens = np.zeros((cell, cell))
        for bx, by, br in blobs:
            cx = (0.5 + bx * spread) * cell
            cy = (0.5 + by * spread) * cell
            rad = br * cell * (1.0 + 0.2 * f)
            dens += np.exp(-((xx - cx) ** 2 + (yy - cy) ** 2) / (2 * rad * rad))
        clump = np.clip((dens - 0.35) / 0.55, 0, 1)
        clump = clump * clump * (3 - 2 * clump)
        if f:
            clump *= np.clip((lace - tear) * 4.0 + 0.2, 0, 1)
        envelope = np.exp(-(rr / (0.26 + 0.05 * f)) ** 4)
        dens = clump * envelope
        for dx, dy, dr in drops[: 8 + f * 10]:
            cx = (0.5 + dx * (0.7 + 0.45 * f)) * cell
            cy = (0.5 + dy * (0.7 + 0.45 * f)) * cell
            rad = dr * cell
            dens += 0.95 * np.exp(-((xx - cx) ** 2 + (yy - cy) ** 2) / (2 * rad * rad))
        # keep the cell's border transparent (no bleeding into a neighbour)
        edge = np.clip(np.minimum(np.minimum(xx, cell - 1 - xx), np.minimum(yy, cell - 1 - yy)) / 4.0, 0, 1)
        a = np.clip(dens, 0, 1) * edge * fade
        # shading: lit from above, darker where the clump is thick and low
        shade = np.clip(1.0 - 0.35 * (yy / cell) * np.clip(dens, 0, 1.2), 0.6, 1.0)
        rgb = np.stack([shade * 245, shade * 250, shade * 255 + 0 * shade], axis=2)
        rgb = rgb * (0.93 + 0.07 * shade[..., None])
        ox, oy = (f % 2) * cell, (f // 2) * cell
        sheet[oy:oy + cell, ox:ox + cell, :3] = rgb
        sheet[oy:oy + cell, ox:ox + cell, 3] = a * 255
    save(sheet, "spray_2x2_sheet.png")


# ── painted (from source art) ────────────────────────────────────────────

def load(src, name):
    return Image.open(os.path.join(src, name)).convert("RGB")


def make_seamless(img, frac=0.25):
    """Offset-and-blend: the classic way to remove a texture's seams."""
    a = np.asarray(img, float)
    h, w = a.shape[:2]
    rolled = np.roll(np.roll(a, w // 2, axis=1), h // 2, axis=0)
    yy, xx = np.mgrid[0:h, 0:w].astype(float)
    # weight for the ORIGINAL: 1 in the middle, 0 at the borders
    wx = np.clip(np.minimum(xx, w - 1 - xx) / (w * frac), 0, 1)
    wy = np.clip(np.minimum(yy, h - 1 - yy) / (h * frac), 0, 1)
    m = (wx * wy)[..., None]
    return Image.fromarray((a * m + rolled * (1 - m)).astype(np.uint8))


def key_magenta(img, soft=60.0):
    """Alpha from distance to the generator's flat magenta-ish backdrop
    (sampled from the corners: it is never exactly #FF00FF)."""
    a = np.asarray(img, float)
    corners = np.concatenate([a[:8, :8].reshape(-1, 3), a[:8, -8:].reshape(-1, 3)])
    bg = np.median(corners, axis=0)
    d = np.linalg.norm(a - bg, axis=2)
    # magenta-ness: high R and B, low G, catches the backdrop's gradients too
    mag = (a[..., 0] + a[..., 2]) / 2 - a[..., 1]
    alpha = np.clip((d - 40) / soft, 0, 1) * np.clip((150 - mag) / 60, 0, 1)
    # un-mix the backdrop from partially covered pixels: C = a*F + (1-a)*B
    al = alpha[..., None]
    rgb = np.where(al > 0.04, (a - (1 - al) * bg[None, None]) / np.maximum(al, 0.04), a)
    rgb = np.clip(rgb, 0, 255)
    return np.concatenate([rgb, alpha[..., None] * 255], axis=2)


def bleed(rgba, passes=8):
    """Fill transparent texels' RGB from their opaque neighbours, so bilinear
    filtering and mip levels at a cutout's silhouette pull in leaf colour, not
    black or backdrop."""
    out = rgba.copy()
    known = out[..., 3] > 127
    rgb = np.where(known[..., None], out[..., :3], 0.0)
    for _ in range(passes):
        acc = np.zeros_like(rgb)
        cnt = np.zeros(known.shape)
        for dy in (-1, 0, 1):
            for dx in (-1, 0, 1):
                if dx == 0 and dy == 0:
                    continue
                k = np.roll(np.roll(known, dy, 0), dx, 1)
                acc += np.roll(np.roll(rgb, dy, 0), dx, 1) * k[..., None]
                cnt += k
        fill = (~known) & (cnt > 0)
        rgb[fill] = acc[fill] / cnt[fill][:, None]
        known = known | fill
    out[..., :3] = np.where(out[..., 3:4] > 127, out[..., :3], rgb)
    return out


def crop_alpha(rgba, pad=4):
    ys, xs = np.nonzero(rgba[..., 3] > 20)
    y0, y1 = max(ys.min() - pad, 0), min(ys.max() + pad, rgba.shape[0])
    x0, x1 = max(xs.min() - pad, 0), min(xs.max() + pad, rgba.shape[1])
    return rgba[y0:y1, x0:x1]


def resize_rgba(rgba, size):
    """Premultiplied resize so the transparent backdrop never bleeds in."""
    a = rgba[..., 3:4] / 255.0
    pm = np.concatenate([rgba[..., :3] * a, a * 255], axis=2).astype(np.float32)
    chans = [np.asarray(Image.fromarray(pm[..., c]).resize(size, Image.LANCZOS)) for c in range(4)]
    out = np.stack(chans, axis=2)
    al = np.clip(out[..., 3:4] / 255.0, 1e-4, 1)
    out[..., :3] = np.where(out[..., 3:4] > 1, out[..., :3] / al, 0)
    return out


def painted(src):
    sand = make_seamless(load(src, "g0.png")).resize((256, 256), Image.LANCZOS)
    sand = np.asarray(sand, float) * np.array([1.0, 0.97, 0.92])
    save(sand, "sand.png")
    save(np.asarray(make_seamless(load(src, "g10.png")).resize((128, 128), Image.LANCZOS)), "rock.png")
    bark = np.asarray(make_seamless(load(src, "g12.png")).resize((64, 128), Image.LANCZOS), float)
    save(bark * np.array([1.0, 0.86, 0.66]), "bark.png")
    save(np.asarray(make_seamless(load(src, "g7.png")).resize((128, 128), Image.LANCZOS)), "planks.png")

    # frond: key, rotate its long axis to +X (stem at the left), crop, 256x64
    fr = key_magenta(load(src, "g3.png"))
    ys, xs = np.nonzero(fr[..., 3] > 128)
    pts = np.stack([xs, ys], 1).astype(float)
    c = pts.mean(0)
    u, s, vt = np.linalg.svd(pts - c, full_matrices=False)
    ang = math.degrees(math.atan2(vt[0, 1], vt[0, 0]))
    im = Image.fromarray(fr.astype(np.uint8), "RGBA").rotate(ang, resample=Image.BICUBIC, expand=True)
    fr = crop_alpha(np.asarray(im, float))
    # the stem is the narrow end: put it at the left
    third = fr.shape[1] // 3
    if (fr[:, :third, 3] > 128).sum() > (fr[:, -third:, 3] > 128).sum():
        fr = fr[:, ::-1]
    save(bleed(resize_rgba(fr, (256, 64))), "frond.png")

    palm = crop_alpha(key_magenta(load(src, "g2.png")))
    save(bleed(resize_rgba(palm, (128, 256))), "palm_far.png")
    shrub = crop_alpha(key_magenta(load(src, "g8.png")))
    save(bleed(resize_rgba(shrub, (128, 128))), "shrub.png")

    # gull: 2-frame flap sheet (wings up = the painting, wings level = the
    # same bird squashed vertically), 64x64 cells → gull_2x1_sheet.png
    gull = crop_alpha(key_magenta(load(src, "g6.png")))
    g1 = resize_rgba(gull, (60, 60))
    g2 = resize_rgba(gull, (60, 26))
    sheet = np.zeros((64, 128, 4))
    sheet[2:62, 2:62] = g1
    sheet[19:45, 66:126] = g2
    save(bleed(sheet), "gull_2x1_sheet.png")

    # sky panorama: horizontally seamless (blend the ends), 256x128
    sky = load(src, "g4.png")
    a = np.asarray(sky, float)
    h, w = a.shape[:2]
    ov = w // 5
    blend = np.linspace(0, 1, ov)[None, :, None]
    a2 = a[:, : w - ov].copy()
    a2[:, :ov] = a[:, :ov] * blend + a[:, w - ov:] * (1 - blend)
    save(np.asarray(Image.fromarray(a2.astype(np.uint8)).resize((256, 128), Image.LANCZOS)), "sky.png")

    # inland: grass ground (a touch less saturated than the painting) and a
    # jungle treeline backdrop, seamless left-right so it can wrap the bay
    g = np.asarray(make_seamless(load(src, "g20.png")).resize((128, 128), Image.LANCZOS), float)
    lum = g.mean(axis=2, keepdims=True)
    save((g * 0.78 + lum * 0.22) * np.array([0.95, 0.92, 0.8]), "grass.png")
    jg = load(src, "g21.png")
    jw, jh = jg.size
    jg = jg.crop((0, 0, jw, int(jh * 0.93)))
    jk = key_magenta(jg, soft=50.0)
    rows = np.nonzero((jk[..., 3] > 128).sum(1) > 0)[0]
    jk = jk[rows.min():]
    h, w = jk.shape[:2]
    ov = w // 6
    bl = np.linspace(0, 1, ov)[None, :, None]
    jw2 = jk[:, : w - ov].copy()
    jw2[:, :ov] = jk[:, :ov] * bl + jk[:, w - ov:] * (1 - bl)
    jw2[..., 3] = np.where(jw2[..., 3] > 110, 255, 0)
    save(bleed(resize_rgba(jw2, (256, 128))), "jungle.png")

    # distant island: keyed, cropped so its waterline IS the bottom edge
    isl = key_magenta(load(src, "g11.png"), soft=90.0)
    # the backdrop fades from magenta to a lavender haze at the horizon, which
    # the distance key keeps: anything not clearly greener than it is sky
    src_rgb = np.asarray(load(src, "g11.png"), float)
    mag = (src_rgb[..., 0] + src_rgb[..., 2]) / 2 - src_rgb[..., 1]
    isl[..., 3] *= np.clip((12 - mag) / 22, 0, 1)
    rows = np.nonzero((isl[..., 3] > 200).sum(1) > 20)[0]
    isl = isl[: rows.max() + 1]
    isl = crop_alpha(isl, pad=2)
    save(resize_rgba(isl, (256, 64)), "island.png")


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--src", help="directory with the source paintings (g0.png ...)")
    args = ap.parse_args()
    os.makedirs(OUT, exist_ok=True)
    sea_frames()
    foam_band()
    sparkle_frames()
    radial(64, lambda d: np.clip(1 - d, 0, 1) ** 2.2 + 0.25 * np.exp(-d * 6), (255, 244, 214), "sun_glow.png")
    radial(32, lambda d: 1 - d, (20, 24, 30), "blob_shadow.png", power=1.6)
    radial(32, lambda d: 1 - d, (255, 255, 255), "spray_puff.png", power=1.4)
    spray_sheet()
    if args.src:
        painted(args.src)
    print("wrote", sorted(os.listdir(OUT)))


if __name__ == "__main__":
    main()
